'use strict';
function calculateOffer(price,quantity,shipping,discount){if(![price,quantity,shipping,discount].every(Number.isFinite)||price<0||quantity<=0||shipping<0||discount<0||discount>price)throw new Error('Confira os valores: quantidade maior que zero e desconto até o valor do produto.');const total=price-discount+shipping;return {total,unit:total/quantity};}
if(typeof module!=='undefined')module.exports={calculateOffer};
if(typeof document!=='undefined'){
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const products=[{id:'vegetal',category:'areia',name:'Areia vegetal sem fragrância',qty:4,unit:'kg',price:39.9,pack:'AREIA\nVEGETAL',color:'#517846',tint:'#edf0d7'},{id:'bentonita',category:'areia',name:'Areia de bentonita sem fragrância',qty:12,unit:'kg',price:59.9,pack:'AREIA\nMINERAL',color:'#bd9558',tint:'#faf0d8'},{id:'racao',category:'alimento',name:'Ração seca para gatos adultos',qty:3,unit:'kg',price:89.9,pack:'RAÇÃO\nADULTOS',color:'#496e60',tint:'#e7eee4'},{id:'sache',category:'alimento',name:'Sachê para gatos · caixa com 12',qty:12,unit:'un',price:35.9,pack:'SACHÊ\nFELINO',color:'#b18060',tint:'#f4e8dc'}];
products.unshift(...(window.MIAU_REAL_PRODUCTS||[]));
let saved=[],stockPlan=null,category='all',onlySaved=false;try{saved=JSON.parse(localStorage.getItem('miau-saved')||'[]');if(!Array.isArray(saved))saved=[];stockPlan=JSON.parse(localStorage.getItem('miau-stock')||'null');}catch{}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{toast('O navegador não permitiu salvar os dados.');}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3000);}
$('#offers-input').innerHTML=['A','B'].map((letter,i)=>`<fieldset class="offer-input" style="margin:0;min-width:0"><legend class="sr-only">Oferta ${letter}</legend><h3>Oferta ${letter}<span>VALORES EM REAIS</span></h3><div class="offer-fields"><label>Loja<select name="store${i}"><option>Amazon</option><option ${i===1?'selected':''}>Shopee</option><option>Mercado Livre</option></select></label><label>Preço do produto (R$)<input name="price${i}" type="number" min="0" step="0.01" placeholder="59,90" required></label><label><span>Quantidade (<span class="unit-label" style="display:inline">kg</span>)</span><input name="qty${i}" type="number" min="0.001" step="any" placeholder="4" required></label><label>Frete (R$)<input name="shipping${i}" type="number" min="0" step="0.01" value="0" required></label><label>Desconto aplicável (R$)<input name="discount${i}" type="number" min="0" step="0.01" value="0" required></label></div></fieldset>`).join('');
$('#unit').addEventListener('change',()=>document.querySelectorAll('.unit-label').forEach(x=>x.textContent=$('#unit').value));
let summary='', initialDemo=true;$('#compare-form').addEventListener('submit',e=>{e.preventDefault();$('#form-error').textContent='';const f=new FormData(e.currentTarget);try{const offers=[0,1].map(i=>({...calculateOffer(Number(f.get('price'+i)),Number(f.get('qty'+i)),Number(f.get('shipping'+i)),Number(f.get('discount'+i))),store:f.get('store'+i),price:Number(f.get('price'+i)),shipping:Number(f.get('shipping'+i)),discount:Number(f.get('discount'+i)),qty:Number(f.get('qty'+i)),letter:i?'B':'A'}));const a=offers[0],b=offers[1],winner=a.unit<=b.unit?a:b,other=winner===a?b:a,tie=Math.abs(a.unit-b.unit)<1e-9,percent=other.unit?((other.unit-winner.unit)/other.unit*100):0;const label=tie?'As ofertas têm o mesmo custo por unidade.':`Oferta ${winner.letter}: ${percent.toFixed(1).replace('.',',')}% menos por ${f.get('unit')}.`;summary=`MiauConta — ${f.get('product')}\n${label}\n`+offers.map(o=>`Oferta ${o.letter} (${o.store}): ${money(o.total)} por ${o.qty} ${f.get('unit')} = ${money(o.unit)}/${f.get('unit')}`).join('\n')+'\nValores informados pelo usuário. Confira as condições na loja. Não é uma cotação automática.';$('#result').innerHTML=`<span class="eyebrow">CONTA FEITA. ESCOLHA SUA.</span><h3>${esc(label)}</h3><p>${esc(f.get('product'))}</p><div class="result-grid">${offers.map(o=>`<div>Oferta ${o.letter} · ${esc(o.store)}<strong>${money(o.unit)}<small> / ${esc(f.get('unit'))}</small></strong>Total ${money(o.total)} · ${o.qty} ${esc(f.get('unit'))}<small class="calculation-line">${money(o.price)} − ${money(o.discount)} + ${money(o.shipping)} de frete</small><small class="calculation-line">${money(o.total)} ÷ ${o.qty} ${esc(f.get('unit'))} = ${money(o.unit)}/${esc(f.get('unit'))}</small></div>`).join('')}</div><p>O resultado compara custo, não qualidade ou rendimento. Confira variante, vendedor e prazo na loja. Valores informados por você; nenhum preço foi consultado automaticamente.</p><button type="button" id="copy-result">Copiar comparação</button>`;$('#result').hidden=false;$('#copy-result').onclick=async()=>{try{await navigator.clipboard.writeText(summary);toast('Comparação copiada para compartilhar.');}catch{toast('Não foi possível copiar. Selecione o resultado e copie manualmente.');}};if(!initialDemo)$('#result').scrollIntoView({behavior:'smooth',block:'nearest'});}catch(err){$('#form-error').textContent=err.message;$('#result').hidden=true;}});
function storeLinks(p){return '<div class="store-links"><span class="commercial-label">Publicidade</span>'+p.links.map(l=>`<a class="button marketplace-link" href="${esc(l.url)}" target="_blank" rel="sponsored nofollow noopener noreferrer" aria-label="Ver ${esc(p.name)} na loja ${esc(l.store)}">Ver ${l.store==='Mercado Livre'?'no':'na'} ${esc(l.store)}</a>`).join('')+'</div>';}
function realCard(p){const labels={alimento:'ALIMENTAÇÃO',areia:'HIGIENE',acessorio:'ACESSÓRIOS',bemestar:'BEM-ESTAR'};return `<article class="product-card real-product" data-product-id="${esc(p.id)}"><button class="save" data-save="${esc(p.id)}" aria-label="${saved.includes(p.id)?'Remover':'Salvar'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button><figure class="product-photo-wrap"><div class="product-image real-product-photo"><img src="${esc(p.image)}" alt="${esc(p.imageAlt)}" width="1000" height="1000" loading="lazy"></div><figcaption>${esc(p.photoCaption)}</figcaption></figure><div class="product-info"><small>${labels[p.category]||'PARA SEU GATO'}</small><h3>${esc(p.name)}</h3><p>${esc(p.note)}</p>${storeLinks(p)}<button class="use-product" data-use="${esc(p.id)}">Comparar minha oferta</button></div></article>`;}

function render(){const query=$('#search').value.toLocaleLowerCase('pt-BR');const shown=products.filter(p=>p.real&&(category==='all'||p.category===category)&&(!onlySaved||saved.includes(p.id))&&p.name.toLocaleLowerCase('pt-BR').includes(query));$('#saved-count').textContent=saved.length;$('#product-grid').innerHTML=shown.map(realCard).join('');$('#empty').hidden=shown.length>0;document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('miau-saved',saved);render();});document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{const p=products.find(p=>p.id===b.dataset.use);if(p.real){selectRealProduct(p);return;}$('#selected-product').hidden=true;$('#product').value=p.name+' · exemplo';$('#unit').value=p.unit;$('#unit').dispatchEvent(new Event('change'));const form=$('#compare-form');form.elements.price0.value=p.price;form.elements.qty0.value=p.qty;form.elements.price1.value=(p.price*1.7).toFixed(2);form.elements.qty1.value=p.qty*2;[0,1].forEach(i=>{form.elements['shipping'+i].value=0;form.elements['discount'+i].value=0;});$('#result').hidden=true;$('#form-error').textContent='';$('#comparar').scrollIntoView({behavior:'smooth'});toast('Exemplo preenchido. Ajuste os valores e compare.');});}
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;onlySaved=false;updateTabs();render();});function updateTabs(){document.querySelectorAll('[data-category]').forEach(b=>{const active=!onlySaved&&b.dataset.category===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('#saved-filter').classList.toggle('active',onlySaved);$('#saved-filter').setAttribute('aria-pressed',onlySaved);}
$('#saved-filter').onclick=()=>{onlySaved=!onlySaved;category='all';updateTabs();render();};$('#saved-nav').onclick=()=>{onlySaved=true;category='all';$('#search').value='';updateTabs();render();$('#descobrir').scrollIntoView({behavior:'smooth'});};$('#search').addEventListener('input',render);
function showStock(){if(!stockPlan)return;const elapsed=Math.max(0,Math.floor((Date.now()-stockPlan.date)/86400000)),remaining=Math.max(0,stockPlan.stock-elapsed*stockPlan.consumption),days=Math.floor(remaining/stockPlan.consumption);$('#stock-result').textContent=`${stockPlan.name}: estoque estimado de ${Math.round(remaining)} g, suficiente para aproximadamente ${days} dia${days===1?'':'s'}. Atualize a quantidade se o consumo mudar.`;}
$('#stock-form').onsubmit=e=>{e.preventDefault();const stock=Number($('#stock').value),consumption=Number($('#consumption').value);if(!Number.isFinite(stock)||!Number.isFinite(consumption)||stock<=0||consumption<=0)return;stockPlan={name:$('#stock-name').value.trim(),stock,consumption,date:Date.now()};persist('miau-stock',stockPlan);showStock();toast('Planejamento salvo neste navegador.');};if(stockPlan&&Number.isFinite(stockPlan.stock)&&stockPlan.consumption>0){$('#stock-name').value=stockPlan.name;$('#stock').value=stockPlan.stock;$('#consumption').value=stockPlan.consumption;showStock();}
function selectRealProduct(p){const f=$('#compare-form');$('#product').value=p.name;$('#unit').value=p.unit;$('#unit').dispatchEvent(new Event('change'));[0,1].forEach(i=>{f.elements['price'+i].value='';f.elements['qty'+i].value='';f.elements['shipping'+i].value=0;f.elements['discount'+i].value=0;});f.elements.store0.value=p.links[0].store;if(p.links[1])f.elements.store1.value=p.links[1].store;$('#result').hidden=true;$('#form-error').textContent='';document.querySelectorAll('[data-example]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});$('#selected-product').innerHTML=`<strong>${esc(p.name)}</strong><p>${esc(p.note)} Informe o preço e a quantidade total de cada oferta para calcular.</p>${storeLinks(p)}`;$('#selected-product').hidden=false;$('#comparar').scrollIntoView({behavior:'smooth'});toast('Produto selecionado. Informe preço e quantidade da sua oferta.');}
function fillExample(id,first=false){$('#selected-product').hidden=true;const p=products.find(p=>p.id===id);if(!p)return;const f=$('#compare-form');$('#product').value=p.name+' · exemplo fictício';$('#unit').value=p.unit;$('#unit').dispatchEvent(new Event('change'));f.elements.price0.value=p.price;f.elements.qty0.value=p.qty;f.elements.price1.value=(p.price*1.7).toFixed(2);f.elements.qty1.value=p.qty*2;f.elements.shipping0.value=10;f.elements.shipping1.value=0;f.elements.discount0.value=0;f.elements.discount1.value=0;document.querySelectorAll('[data-example]').forEach(b=>{b.classList.toggle('active',b.dataset.example===id);b.setAttribute('aria-pressed',b.dataset.example===id);});initialDemo=first;f.requestSubmit();initialDemo=false;}
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>fillExample(b.dataset.example));
$('#stock-example').onclick=()=>{$('#stock-name').value='Ração do meu gato · exemplo';$('#stock').value=1200;$('#consumption').value=60;$('#stock-form').requestSubmit();$('#stock-result').scrollIntoView({behavior:'smooth',block:'nearest'});};
fillExample('vegetal',true);
$('#clear-data').onclick=()=>{if(!confirm('Apagar os produtos salvos e o planejamento deste navegador?'))return;try{localStorage.removeItem('miau-saved');localStorage.removeItem('miau-stock');}catch{}saved=[];stockPlan=null;$('#stock-form').reset();$('#stock-result').textContent='A estimativa usa seu consumo informado. Não recomenda porção alimentar.';render();toast('Seus dados locais foram apagados.');};render();
}

